#!/usr/bin/env python3
"""Generates the Scene probe scripts in ../scenes (inputs only; the goldens
are produced by the reference with KREMENMC_REF=1 go test)."""
import os

HERE = os.path.dirname(os.path.abspath(__file__))
OUT = os.path.join(HERE, '..', 'scenes')

SPAWN_LIST_MOBS = """armadillo axolotl bat blaze bogged camel cat cave_spider chicken cod cow creeper dolphin donkey drowned
enderman fox frog ghast glow_squid goat guardian hoglin horse husk llama magma_cube mooshroom nautilus ocelot panda
parched parrot pig piglin pillager polar_bear pufferfish rabbit salmon sheep skeleton slime spider squid stray strider
sulfur_cube tropical_fish turtle witch wither_skeleton wolf zombie zombie_horse zombie_villager zombified_piglin""".split()

WALK_MOBS = """zombie cow enderman axolotl guardian hoglin mooshroom nautilus pillager strider turtle cod ocelot drowned
zombified_piglin bat ghast slime squid camel""".split()

# (floor, at pos, above pos)
CELLS = [
    ('grass_block', None, None), ('stone', None, None), ('sand', None, None), ('red_sand', None, None),
    ('snow_block', None, None), ('ice', None, None), ('packed_ice', None, None), ('mycelium', None, None),
    ('podzol', None, None), ('coarse_dirt', None, None), ('oak_leaves[persistent=true]', None, None), ('moss_block', None, None),
    ('mud', None, None), ('gravel', None, None), ('terracotta', None, None), ('nether_wart_block', None, None),
    ('netherrack', None, None), ('magma_block', None, None), ('soul_sand', None, None), ('nether_bricks', None, None),
    ('glass', None, None), ('stone_slab[type=bottom]', None, None), ('stone_slab[type=top]', None, None),
    ('water', 'water', 'water'), ('lava', 'lava', None), ('grass_block', None, 'powder_snow'), ('clay', None, None),
    ('bedrock', None, None), ('grass_block', 'white_carpet', None), ('grass_block', 'redstone_torch', None),
    ('grass_block', 'rail', None), ('dirt', None, None),
]

X0, Z0 = 4000, 4000
ROWS = {'open': 4006, 'roof': 4018, 'lit': 4030, 'cave': 4040}


def base(lines, biome, time, difficulty='hard', weather='clear'):
    x1, z1 = X0 + 3 * len(CELLS) + 3, Z0 + 47
    lines += [
        f'area {X0} -64 {Z0} {x1} -50 {z1}',
        f'setup fill {X0} -63 {Z0} {x1} 8 {z1} minecraft:air',
        f'setup fill {X0} -64 {Z0} {x1} -64 {z1} minecraft:bedrock',
        f'setup fill {X0} -63 {Z0} {x1} -62 {z1} minecraft:stone',
        f'setup fill {X0} -61 {Z0} {x1} -61 {z1} minecraft:grass_block',
        f'setup fill {X0} -57 {ROWS["roof"] - 6} {x1} -57 {ROWS["roof"] + 6} minecraft:stone',
        f'setup fill {X0} -60 {ROWS["cave"] - 2} {x1} -57 {ROWS["cave"] + 2} minecraft:stone',
        f'setup fill {X0 + 1} -60 {ROWS["cave"] - 1} {x1 - 1} -58 {ROWS["cave"] + 1} minecraft:air',
        f'setup fillbiome {X0} -64 {Z0} {x1} 8 {z1} minecraft:{biome}',
        f'setup time set {time}',
        f'setup difficulty {difficulty}',
        f'setup weather {weather}',
    ]
    for i, (floor, at, above) in enumerate(CELLS):
        x = X0 + 2 + 3 * i
        for row, z in ROWS.items():
            if floor in ('water', 'lava'):
                wall = 'glass' if floor == 'water' else 'stone'
                top = -59 if floor == 'water' else -60
                lines.append(f'setup fill {x - 1} -61 {z - 1} {x + 1} {top} {z + 1} minecraft:{wall}')
            if floor != 'grass_block':
                lines.append(f'setup setblock {x} -61 {z} minecraft:{floor}')
            if at:
                lines.append(f'setup setblock {x} -60 {z} minecraft:{at}')
            if above:
                lines.append(f'setup setblock {x} -59 {z} minecraft:{above}')
                if above == 'powder_snow':
                    lines.append(f'setup setblock {x} -58 {z} minecraft:{above}')
            if row == 'lit':
                lines.append(f'setup setblock {x} -59 {z - 1} minecraft:glowstone')


def cell_positions():
    for i, _ in enumerate(CELLS):
        for row, z in ROWS.items():
            yield X0 + 2 + 3 * i, z


def write(name, lines):
    with open(os.path.join(OUT, name + '.txt'), 'w') as f:
        f.write('# generated by testdata/gen/scenes.py\n' + '\n'.join(lines) + '\n')


def matrix(name, biome, time, mobs, walk, seed0, **kw):
    lines = []
    base(lines, biome, time, **kw)
    lines.append(f'player {X0 + 48}.5 -60 {Z0 + 44}.5')
    seed = seed0
    for x, z in cell_positions():
        for m in mobs:
            seed += 1
            lines.append(f'rules minecraft:{m} {x} -60 {z} {seed}')
        for m in walk:
            seed += 1
            lines.append(f'mobcheck minecraft:{m} {x} -60 {z} {seed}')
    write(name, lines)


def main():
    matrix('matrix_plains_night', 'plains', 18000, SPAWN_LIST_MOBS, WALK_MOBS, 1000)
    animals = [m for m in SPAWN_LIST_MOBS if m in """armadillo camel cat chicken cow donkey fox frog goat horse llama mooshroom
        panda parrot pig polar_bear rabbit sheep turtle wolf ocelot zombie skeleton husk stray parched bat slime""".split()]
    matrix('matrix_plains_day', 'plains', 6000, animals, ['zombie', 'cow', 'mooshroom', 'turtle'], 50000)
    matrix('matrix_swamp_night', 'swamp', 18000, ['slime', 'drowned', 'frog', 'witch', 'bat', 'polar_bear'], [], 70000)
    matrix('matrix_snowy_thunder', 'snowy_plains', 18000, ['polar_bear', 'stray', 'zombie', 'rabbit', 'fox', 'husk'], ['zombie'], 80000, weather='thunder')
    matrix('matrix_peaceful', 'plains', 18000, ['zombie', 'slime', 'ghast', 'magma_cube', 'cow', 'zombified_piglin', 'piglin', 'blaze', 'sulfur_cube', 'bat', 'drowned', 'guardian'], [], 90000, difficulty='peaceful')
    water('water_night', 18000, 400000)
    water('water_day', 6000, 450000)
    dynamics('dynamics_day', 6000, 200000)
    dynamics('dynamics_night', 18000, 300000)


def dynamics(name, time, seed0):
    x0, z0, x1, z1 = 4000, 4000, 4095, 4095
    L = [
        f'area {x0 - 24} -64 {z0 - 24} {x1 + 24} -50 {z1 + 24}',
        f'setup fill {x0} -63 {z0} {x1} 8 {z1} minecraft:air',
        f'setup fill {x0} -64 {z0} {x1} -64 {z1} minecraft:bedrock',
        f'setup fill {x0} -63 {z0} {x1} -62 {z1} minecraft:dirt',
        f'setup fill {x0} -61 {z0} {x1} -61 {z1} minecraft:grass_block',
        f'setup fillbiome {x0} -64 {z0} {x1} 8 {z1} minecraft:plains',
        # dark hall: stone box with a single opening
        'setup fill 4064 -61 4000 4095 -55 4031 minecraft:stone',
        'setup fill 4065 -60 4001 4094 -57 4030 minecraft:air',
        # ocean pond at the world floor (sea level -63)
        'setup fill 4000 -64 4064 4031 -61 4095 minecraft:water',
        'setup fill 3999 -64 4063 4032 -61 4063 minecraft:glass',
        'setup fill 3999 -64 4096 4032 -61 4096 minecraft:glass',
        'setup fill 3999 -64 4063 3999 -61 4096 minecraft:glass',
        'setup fill 4032 -64 4063 4032 -61 4096 minecraft:glass',
        'setup fill 4000 -61 4064 4031 -61 4095 minecraft:air',
        'setup fillbiome 4000 -64 4064 4031 8 4095 minecraft:warm_ocean',
        # obstruction: a mob already standing in the field
        'setup summon minecraft:armor_stand 4040.5 -60 4040.5 {NoGravity:1b}',
        f'setup time set {time}',
        'setup difficulty normal',
        'player 4048.5 -60 4048.5',
        'worldspawn 0 0 0',
    ]
    seed = seed0
    def nxt():
        nonlocal seed
        seed += 1
        return seed
    for i in range(24):
        L.append(f'natural creature {4004 + (i * 7) % 56} -60 {4004 + (i * 13) % 56} {nxt()}')
    for i in range(24):
        L.append(f'natural monster {4066 + (i * 5) % 28} -60 {4002 + (i * 11) % 28} {nxt()}')
    for i in range(16):
        L.append(f'natural monster {4004 + (i * 7) % 56} -60 {4004 + (i * 13) % 56} {nxt()}')
    for i in range(12):
        L.append(f'natural water_creature {4002 + (i * 5) % 28} -63 {4066 + (i * 7) % 28} {nxt()}')
        L.append(f'natural water_ambient {4002 + (i * 3) % 28} -63 {4066 + (i * 11) % 28} {nxt()}')
    for cx in range(250, 256):
        for cz in range(250, 256):
            L.append(f'chunk monster {cx} {cz} {nxt()}')
            L.append(f'chunk creature {cx} {cz} {nxt()}')
    for cx in range(250, 254):
        for cz in range(250, 253):
            for k in range(4):
                L.append(f'gen {cx} {cz} {nxt()}')
    for d, na in [(10, 0), (40, 700), (40, 0), (100, 700), (140, 0), (140, 700)]:
        for typ in ['zombie', 'cow', 'cod', 'bat', 'enderman']:
            for flags in ['none', 'named', 'persistent']:
                L.append(f'despawn minecraft:{typ} {4048.5 + d} -60 4048.5 {na} {flags} {nxt()}')
    L.append(f'spawner minecraft:zombie 4080 -59 4016 60 5 10 40 4 6 4 64 {nxt()}')
    L.append(f'spawner minecraft:pig 4040 -59 4060 60 0 10 40 4 3 4 64 {nxt()}')
    L.append(f'spawner minecraft:skeleton 4080 -59 4016 30 -1 200 800 4 6 4 64 {nxt()}')
    write(name, L)



WATER_MOBS = """cod salmon pufferfish tropical_fish squid glow_squid dolphin axolotl drowned guardian nautilus turtle
strider""".split()

POOLS = [  # x0, biome, floor, fluid, covered
    (4002, 'warm_ocean', 'sand', 'water', False),
    (4018, 'river', 'clay', 'water', False),
    (4034, 'lush_caves', 'clay', 'water', True),
    (4050, 'deep_ocean', 'gravel', 'water', False),
    (4066, 'nether_wastes', 'netherrack', 'lava', False),
]


def water(name, time, seed0):
    L = [
        'area 3998 -64 3998 4081 -20 4013',
        'sealevel -30',
        'setup fill 3998 -64 3998 4081 8 4013 minecraft:air',
        'setup fill 3998 -64 3998 4081 -64 4013 minecraft:stone',
        f'setup time set {time}',
        'setup difficulty hard',
        'player 4040.5 -20 4040.5',
    ]
    for x0, biome, floor, fluid, covered in POOLS:
        x1 = x0 + 11
        L += [
            f'setup fill {x0 - 1} -64 3999 {x1 + 1} -29 4012 minecraft:glass',
            f'setup fill {x0} -64 4000 {x1} -64 4011 minecraft:{floor}',
            f'setup fill {x0} -63 4000 {x1} -30 4011 minecraft:{fluid}',
            f'setup fill {x0 - 1} -29 3999 {x1 + 1} -29 4012 minecraft:air',
            f'setup fillbiome {x0 - 1} -64 3999 {x1 + 1} 8 4012 minecraft:{biome}',
        ]
        if covered:
            L.append(f'setup fill {x0 - 1} -29 3999 {x1 + 1} -28 4012 minecraft:stone')
    seed = seed0
    for x0, biome, floor, fluid, covered in POOLS:
        for dx, dz in [(2, 2), (6, 9)]:
            for y in [-63, -62, -50, -44, -43, -40, -36, -33, -31, -30, -29]:
                for m in WATER_MOBS:
                    seed += 1
                    L.append(f'rules minecraft:{m} {x0 + dx} {y} {4000 + dz} {seed}')
        for y in [-63, -40, -30, -29]:
            for m in ['cod', 'squid', 'axolotl', 'guardian', 'nautilus', 'strider', 'turtle', 'drowned', 'dolphin']:
                seed += 1
                L.append(f'mobcheck minecraft:{m} {x0 + 5} {y} 4005 {seed}')
    write(name, L)


if __name__ == '__main__':
    main()
